Here is a minimal self-contained HTML file. The "DVD" text moves in a straight line and bounces off the walls:

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>DVD Logo</title>
<style>
  html,body{margin:0;height:100%;overflow:hidden;background:#000}
  #logo{
    position:absolute;
    font-family:sans-serif;
    font-size:48px;
    color:#fff;
    left:0;top:0;
  }
</style>
</head>
<body>
<div id="logo">DVD</div>
<script>
const logo = document.getElementById('logo');
let x = 100, y = 100;
let vx = 3, vy = 2;
const w = logo.offsetWidth, h = logo.offsetHeight;

function frame(){
  x += vx;
  y += vy;
  if(x <= 0 || x + w >= innerWidth) vx *= -1;
  if(y <= 0 || y + h >= innerHeight) vy *= -1;
  logo.style.left = x + 'px';
  logo.style.top = y + 'px';
  requestAnimationFrame(frame);
}
frame();
</script>
</body>
</html>
